<template>
  <div class="report-view">
    <NavBarVue />
    <b-container fluid class="bv-example-row">
      <div class="container-group">
        <div class="card">
          <div class="card-body">
            <!-- Reports -->
            <b-overlay :show="isLoading" rounded="sm">
              <b-row>
                <b-col>
                  <!-- <h5 class="text-dark">{{ $t("received_payments") }}</h5> -->
                  <b-row class="mb-1">
                    <!-- <b-col
                      ><b-form-select
                        v-model="selectedPaymentMethod"
                        :options="options"
                      ></b-form-select
                    ></b-col> -->
                    <b-col>
                      <b-form-datepicker
                        placeholder="M"
                        block
                        size="sm"
                        id="from-datepicker"
                        v-model="fromDate"
                      ></b-form-datepicker
                    ></b-col>
                    <b-col
                      ><b-form-datepicker
                        placeholder="Até"
                        block
                        size="sm"
                        id="to-datepicker"
                        v-model="toDate"
                      ></b-form-datepicker
                    ></b-col>
                    <b-col cols="1"
                      ><b-button
                        @click="getTranzactions()"
                        :disabled="(!toDate && !fromDate) || isLoading"
                        size="sm"
                        variant="secondary"
                        block
                        ><b-icon icon="search"></b-icon> </b-button
                    ></b-col>
                    <b-col cols="1"
                      ><b-button
                        @click="generateExcelReport()"
                        :disabled="tranzactions.length == 0"
                        size="sm"
                        variant="secondary"
                        block
                        >Excel
                        <b-icon icon="file-excel-fill"></b-icon> </b-button
                    ></b-col>
                    <b-col cols="1"
                      ><b-button
                        @click="generatePDFReport()"
                        :disabled="tranzactions.length == 0"
                        size="sm"
                        variant="secondary"
                        block
                        >Pdf <b-icon icon="printer-fill"></b-icon> </b-button
                    ></b-col>
                  </b-row>

                  <table
                    class="table table-sm table-hover table-stripped"
                    v-if="tranzactions.length > 0"
                  >
                    <thead>
                      <tr style="font-size: 12pt" class="text-secondary">
                        <th colspan="6">
                          Total de crédito reembolsado:
                          {{ fromDate + " a " + toDate }}
                        </th>
                        <th
                          colspan="4"
                          class="text-right"
                          v-money-format="calculateTotalCollected()"
                        ></th>
                      </tr>
                    </thead>
                    <thead>
                      <tr class="bg-secondary text-white">
                        <th>Nome do mutuário</th>
                        <th>Número da conta</th>
                        <th>Data de pagamento</th>
                        <th>Referência</th>
                        <th>Telemóvel</th>
                        <th>Meio de pagamento</th>
                        <th>Técnico</th>
                        <th>Juros de mora</th>
                        <th class="text-right">Total pago</th>
                      </tr>
                    </thead>
                    <tbody>
                      <tr
                        v-for="tranzaction in tranzactions"
                        :key="tranzaction.id"
                      >
                        <td>
                          {{
                            getCustomerDetails(tranzaction.accountNumber)
                              .customerName
                          }}
                        </td>
                        <td>{{ tranzaction.accountNumber }}</td>
                        <td v-date-format="tranzaction.createdAt"></td>
                        <td>{{ tranzaction.tranzactionReference }}</td>
                        <td>
                          {{
                            tranzaction.phoneNumber == null
                              ? "Não disponível"
                              : tranzaction.phoneNumber
                          }}
                        </td>
                        <td>
                          {{ getPaymentMethod(tranzaction.paymentMethod) }}
                        </td>
                        <td>{{ tranzaction.staffName }}</td>
                        <td
                          class="text-right"
                          v-money-format="tranzaction.latePaymentInterest"
                        ></td>
                        <td
                          class="text-right"
                          v-money-format="tranzaction.amount"
                        ></td>
                      </tr>
                    </tbody>
                  </table>
                  <b-alert
                    class="text-center"
                    v-if="tranzactions.length === 0"
                    variant="danger"
                    show
                    dismissible
                    ><b-icon
                      icon="exclamation-circle-fill"
                      variant="danger"
                    ></b-icon>
                    Sem nenhuma transação registada até o momento.
                    <!-- <b>&rArr;</b> -->
                  </b-alert>
                </b-col>
              </b-row>
            </b-overlay>
          </div>
        </div>
      </div>
    </b-container>
  </div>
</template>

<script>
import { mapGetters } from "vuex";

import NavBarVue from "@/components/NavBar";
import moment from "moment";
import axios from "axios";
import MoneyFormat from "@/utils/moneyFormat";
import DateFormat from "@/utils/dateFormat";
import exportFromJSON from "export-from-json";

import pdfMake from "pdfmake/build/pdfmake";
import pdfFonts from "pdfmake/build/vfs_fonts";
pdfMake.vfs = pdfFonts.pdfMake.vfs;

export default {
  data: () => ({
    fromDate: moment().format("YYYY-MM-01"),
    toDate: moment().format("YYYY-MM-") + moment().daysInMonth(),

    selectedPaymentMethod: 0,

    options: [
      { value: 0, text: "Meio de pagamento" },
      { value: 1, text: "Boca de Caixa" },
      { value: 2, text: "Depósito Bancário" },
      { value: 3, text: "Transferência Bancária" },
      { value: 4, text: "POS" },
      { value: 5, text: "Cheque" },
      { value: 6, text: "SISTAFE" },
      { value: 7, text: "M-Pesa Open-Api" },
      { value: 8, text: "E-Mola" },
    ],

    totalRecebido: 0,
    tranzactions: [],
  }),

  components: {
    NavBarVue,
  },

  computed: {
    ...mapGetters([
      "isLoading",
      "user",
      "token",
      "customers",
      "company",
      "updatedPassword",
    ]),
  },

  created() {
    this.checkPasswordStatus();
    this.getTranzactions();
  },

  methods: {
    checkPasswordStatus() {
      this.user.updatedPassword == 1 ? "" : this.$router.replace("/profile");
    },

    getPaymentMethod(method) {
      if (method == 1) {
        return "Boca do Caixa";
      } else if (method == 2) {
        return "Depósito Bancário";
      } else if (method == 3) {
        return "Transferência Bancária";
      } else if (method == 4) {
        return "POS";
      } else if (method == 5) {
        return "Cheque";
      } else if (method == 6) {
        return "SISTAFE";
      } else if (method == 7) {
        return "M-Pesa Open-Api";
      } else if (method == 8) {
        return "E-Mola";
      }
    },

    getTranzactions() {
      this.$store.commit("LOADING_STATUS", true);
      const queryString = `?from=${this.fromDate}&to=${this.toDate}&companyId=${this.company.id}`;
      axios
        .get(`/api/tranzaction/${queryString}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.tranzactions = data.result;
          } else {
            this.showToast("Opps!", "warning", "Reembolsos indisponíveis.");
            this.tranzactions = [];
          }
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
          this.tranzactions = [];
        });
    },

    generateExcelReport() {
      const body = [];

      for (let tranzaction of this.tranzactions) {
        const row = {
          "Nome do mutuário": this.getCustomerDetails(tranzaction.accountNumber)
            .customerName,
          "Número da conta": tranzaction.accountNumber,
          "Data de pagamento": tranzaction.createdAt,
          Referência: tranzaction.TranzactionReference,
          Telemóvel:
            tranzaction.phoneNumber == null
              ? "Não disponível"
              : tranzaction.phoneNumber,
          "Meio de pagamento": this.getPaymentMethod(tranzaction.paymentMethod),
          Técnico: tranzaction.staffName,
          Montante: tranzaction.amount,
        };
        body.push(row);
      }
      const fileName = "Reembolsos" + this.fromDate + "_A_" + this.toDate;
      const data = body;
      const exportType = "xls";

      exportFromJSON({ data, fileName, exportType });
    },

    async generatePDFReport() {
      const body = [];

      for (let row of this.tranzactions) {
        const rows = [];

        // rows.push({ text: row.id, fontSize: 8 })
        rows.push({
          text: this.getCustomerDetails(row.accountNumber).customerName,
          fontSize: 7,
        });
        rows.push({ text: row.accountNumber, fontSize: 7 });
        rows.push({ text: DateFormat.formatDate(row.createdAt), fontSize: 7 });
        rows.push({ text: row.tranzactionReference, fontSize: 7 });
        rows.push({
          text: row.phoneNumber == null ? "Não disponível" : row.phoneNumber,
          fontSize: 7,
        });
        rows.push({
          text: this.getPaymentMethod(row.paymentMethod),
          fontSize: 7,
        });
        rows.push({ text: row.staffName, fontSize: 7 });
        rows.push({ text: MoneyFormat.formatMoney(row.amount), fontSize: 7 });

        body.push(rows);
      }

      let docDefinition = {
        // watermark: { text: this.company[0].name, opacity: 0.08 },
        pageOrientation: "landscape",
        header: [
          // {
          //   image: await getBase64ImageFromURL(this.company.companyLogo),
          //   width: 300,
          //   height: 200,
          //   margin: [30, 0, 0, 0],
          // },
        ],
        footer: {
          columns: [
            {
              text: "Documento processado por computador",
              alignment: "left",
              fontSize: 8,
              margin: [30, 0, 0, 0],
            },
            {
              text: "Microcrédito Software",
              alignment: "right",
              fontSize: 8,
              margin: [0, 0, 30, 0],
            },
          ],
        },

        content: [
          {
            columns: [
              [
                {
                  text: `\nData de impressão: ${DateFormat.formatDate(
                    new Date()
                  )}`,
                  fontSize: 8,
                  alignment: "left",
                },
              ],
            ],
          },
          {
            text: "\n",
          },
          {
            text: `Mapa de crédito reembolsado de ${this.fromDate} à ${this.toDate}`,
            bold: true,
            fontSize: 10,
            alignment: "left",
          },
          {
            text: `Total reembolsado: ${MoneyFormat.formatMoney(
              this.calculateTotalCollected()
            )}`,
            bold: true,
            fontSize: 10,
            alignment: "left",
          },
          {
            text: "\n",
          },
          {
            table: {
              widths: [
                "*",
                "auto",
                "auto",
                "auto",
                "auto",
                "auto",
                "auto",
                "auto",
              ],
              body: [
                [
                  { text: "Nome do mutuário", style: "columnsTitle" },
                  { text: "Conta", style: "columnsTitle" },
                  { text: "Data", style: "columnsTitle" },
                  { text: "Referência", style: "columnsTitle" },
                  { text: "Telemóvel", style: "columnsTitle" },
                  { text: "Canal", style: "columnsTitle" },
                  { text: "Técnico", style: "columnsTitle" },
                  { text: "Montante", style: "columnsTitle" },
                ],
                ...body,
                [{ text: "\n\n" }, {}, {}, {}, {}, {}, {}, {}],
              ],
            },
            layout: "lightHorizontalLines",
          },
        ],
        styles: {
          paymentMethodStyle: {
            bold: true,
            fontSize: 10,
          },
          sectionHeader: {
            bold: true,
            fontSize: 8,
            margin: [0, 15, 0, 15],
          },
          columnsTitle: {
            fontSize: 8,
            bold: true,
            color: "#000000",
          },
          columnsSubTotals: {
            fontSize: 10,
            bold: true,
            color: "#000000",
          },
          columnsTotal: {
            fontSize: 12,
            bold: true,
            color: "#000000",
          },
          companyDetailsStyle: {
            fontSize: 9,
            bold: true,
            color: "#000000",
          },
          customerStyle: {
            fontSize: 10,
            bold: false,
          },
        },
      };

      // pdfMake.createPdf(docDefinition).download(`proforma${this.currentQuotation.name}.pdf`);
      pdfMake.createPdf(docDefinition).open();
    },

    getCustomerDetails(accountNumber) {
      const filteredCustomer = this.customers.filter((a) => {
        return a.accountNumber == accountNumber;
      });
      return filteredCustomer[0];
    },

    calculateTotalCollected() {
      return MoneyFormat.calculateSumOfArray(this.tranzactions);
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(`${msg}`, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 5000,
      });
    },
  },
};
</script>
<style lang="scss" scoped>
.container-group {
  overflow: hidden auto;
  margin-left: -15px;
  width: calc(100% + 30px);
  height: calc(100vh - 55px);

  .container {
    font-size: 10pt;
    padding-top: 0px;
    padding-bottom: 15px;
  }
}

.table {
  font-size: 10pt;
  text-align: left;

  tr {
    cursor: pointer;
  }
}
</style>
